#define HEAP_MAGIC 0x434f444558484541ull
struct heap_header{uint64_t magic,pages,physical,size;};static int heap_ready;void*ha(uint64_t size){uint64_t overhead=sizeof(struct heap_header)+PG-1u;if(!heap_ready||!size||size>UINT64_MAX-overhead)return 0;uint64_t pages=(size+overhead)/PG,physical=mpas(pages);if(!physical)return 0;struct heap_header*header=mpv(physical);if(!header){(void)mpfs(physical,pages);return 0;}header->magic=HEAP_MAGIC;header->pages=pages;header->physical=physical;header->size=size;return header+1;}int hf(void*pointer){if(!heap_ready||!pointer)return 0;struct heap_header*header=(struct heap_header*)pointer-1;if(header->magic!=HEAP_MAGIC||!header->pages||!header->physical||mpv(header->physical)!=(void*)header)return 0;uint64_t physical=header->physical,pages=header->pages;header->magic=0;if(mpfs(physical,pages))return 1;header->magic=HEAP_MAGIC;return 0;}int hi(void){heap_ready=1;uint8_t*test=ha(17);if(!test){heap_ready=0;return 0;}for(uint32_t i=0;i<17;++i)test[i]=(uint8_t)i;if(!hf(test)||hf(test)){heap_ready=0;return 0;}return 1;}
